function populateBeatMenus(b){const mi=meterInfo(),step=mi.compound?1:.5,menu=$('editBeats');menu.innerHTML='';const durationLabel=n=>{let note=mi.d===4?({'0.5':'八分音符',1:'四分音符',2:'二分音符',4:'全音符'}[String(n)]):({1:'八分音符',2:'四分音符',3:'附點四分音符',6:'附點二分音符'}[String(n)]);return n+' 拍'+(n%mi.n===0?'（'+(n/mi.n)+' 小節）':note?'（'+note+'）':'')};for(let n=step;n<=64;n+=step)menu.add(new Option(durationLabel(n),n));if(![...menu.options].some(o=>Number(o.value)===b.beats)){const option=new Option(b.beats+' 拍（既有值）',b.beats);option.disabled=true;menu.add(option)}menu.value=b.beats;const offset=$('editOffset');offset.innerHTML='';if(mi.compound)startOffset=Math.floor(startOffset);startOffset=Math.max(0,Math.min(startOffset,b.beats-step));for(let t=0;t<b.beats-1e-7;t+=step){const beat=Math.floor(t)+1;offset.add(new Option('第 '+beat+' 拍'+(t%1?'後半':''),t+1))}offset.value=startOffset+1}
