function makeDownload(name,text,mime){const url=URL.createObjectURL(new Blob([text],{type:mime})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function dragPreview(text,x,y){let box=document.getElementById('dragPreview');if(!box){box=document.createElement('div');box.id='dragPreview';box.className='drag-preview';document.body.append(box)}box.textContent=text;box.style.left=x+'px';box.style.top=y+'px';return box}
function installPointerDrop(button,payload,label,resolve,onTap){let state=null;const clear=()=>{document.getElementById('dragPreview')?.remove();document.querySelectorAll('.bank-drop-target').forEach(n=>n.classList.remove('bank-drop-target'));state=null};button.onpointerdown=e=>{if(e.button>0)return;e.preventDefault();stop();state={pointer:e.pointerId,x:e.clientX,y:e.clientY,active:false};button.setPointerCapture?.(e.pointerId)};button.onpointermove=e=>{if(!state||state.pointer!==e.pointerId)return;e.preventDefault();if(!state.active&&Math.hypot(e.clientX-state.x,e.clientY-state.y)<6)return;state.active=true;dragPreview(label,e.clientX,e.clientY);resolve(payload,e.clientX,e.clientY,false)};button.onpointerup=e=>{if(!state||state.pointer!==e.pointerId)return;const active=state.active;try{button.releasePointerCapture?.(e.pointerId)}catch(err){}clear();if(active){resolve(payload,e.clientX,e.clientY,true);clear()}else if(onTap)onTap(payload)};button.onpointercancel=clear;button.onlostpointercapture=()=>{if(state)clear()};button.onclick=e=>{if(e.detail===0&&onTap)onTap(payload)}}
function insertSongRoot(rootPc,index){if(song.blocks.length>=256){songMessage('最多 256 格。');return}stop();const block=newBlock(rootPc,0);block.beats=meterInfo().n;block.pattern='singHold';index=Math.max(0,Math.min(song.blocks.length,index));song.blocks.splice(index,0,block);selected=index;startOffset=0;pausedAt=null;renderSong();openBasicEditor();songMessage('已加入 '+blockSymbol(block)+'，可先選後綴與拍長。')}
function resolveSongRootDrop(payload,x,y,commit){const hit=document.elementFromPoint(x,y),card=hit?.closest('.song-card'),studio=hit?.closest('#songChartStudio');document.querySelectorAll('.bank-drop-target').forEach(n=>n.classList.remove('bank-drop-target'));let index=null;if(card){const i=Number(card.id.slice(8)),rect=card.getBoundingClientRect();index=i+(x>rect.left+(rect.right-rect.left)/2?1:0);card.classList.add('bank-drop-target')}else if(studio){index=song.blocks.length;$('songChart').classList.add('bank-drop-target')}if(index===null)return false;if(commit)insertSongRoot(payload.root,index);else{const rect=$('songChart').getBoundingClientRect();if(x>rect.right-30)$('songChart').scrollLeft+=12;if(x<rect.left+30)$('songChart').scrollLeft-=12}return true}
function renderSongRootBank(){const bank=$('songRootBank');bank.innerHTML='';songNames().forEach((name,root)=>{const b=document.createElement('button');b.className='root-token';b.textContent=name;b.setAttribute('aria-label','拖曳 '+name+' 到和弦譜，點一下加入結尾');installPointerDrop(b,{root},name,resolveSongRootDrop,p=>insertSongRoot(p.root,song.blocks.length));bank.append(b)})}
function patternDiagram(id,block=null,settings=null){const dual=id.startsWith('sing'),b=block?{...block}:{root,quality:Number($('quality').value)||0,inv,voicing:dual&&$('exploreVoicing').value==='no5'?'no5':'compact',bass:null,beats:id==='singWaltz'||id==='waltz'?3:4};b.pattern=id;settings=settings||{meter:'4/4',bpm:76,division:2,register:Number($('octave').value)-12};b.beats=Math.min(b.beats,6);const duration=b.beats,events=patternValid(b)?blockEvents(b,settings):[],height=dual?62:43,left=21,span=170;let svg='<svg viewBox="0 0 196 '+height+'" class="rhythm-diagram" role="img" aria-label="'+patternTitle(id)+'節奏示意">';if(dual)svg+='<text x="2" y="28" fill="#397b65">R</text><text x="2" y="53" fill="#b87042">L</text>';else svg+='<text x="1" y="30" fill="#567361">音</text>';for(let i=0;i<=Math.ceil(duration);i++){const x=left+span*i/duration;svg+='<path d="M'+x+' 12V'+height+'" stroke="#d6dfd0" stroke-width=".7"/><text x="'+(x+2)+'" y="9" fill="#7b8e7c" font-size="7">'+(i<duration?i+1:'')+'</text>'}for(let e of events){const x=left+span*e.t/duration,width=Math.max(3,Math.min(span*e.duration/duration-1,span-(x-left))),labels=e.ns.map(n=>{const i=qualities[b.quality][2].findIndex(v=>(v+b.root)%12===n%12);return qualities[b.quality][3][i]||'根'}),fill=dual?(e.hand==='left'?'#df9864':'#67ab90'):'#79a38f',y=dual?(e.hand==='right'?16:41):17;svg+='<rect x="'+x+'" y="'+y+'" width="'+width+'" height="17" rx="3" fill="'+fill+'" opacity=".88"/>';if(width>=13)svg+='<text x="'+(x+width/2)+'" y="'+(y+11)+'" text-anchor="middle" fill="#153f31" font-size="7">'+(labels.length>3&&width<50?labels.length+'音':labels.join('·'))+'</text>'}return svg+'</svg>'}
function refreshPatternDiagrams(){document.querySelectorAll('.pattern').forEach((button,i)=>{const p=pats[i];if(!p)return;if(p.group==='basic')button.hidden=true;button.innerHTML='<span class="pattern-title">'+p.title+'</span>'+patternDiagram(p.id)+'<small>'+(p.id.startsWith('sing')?'R 右手在上／L 左手在下':'單一伴奏聲部')+' · 格內為和弦音級</small>'});const basics=$('basicPatterns');basics.innerHTML='';pats.forEach((p,i)=>{if(p.group!=='basic'||!levelPatternAllowed(p.id))return;const b=document.createElement('button');b.className='basic-pattern'+(pattern===i?' active':'');b.innerHTML='<span>'+p.title+'</span>'+patternDiagram(p.id);b.onclick=()=>{pattern=i;update()};basics.append(b)});if(window._songReady)$('editPatternDiagram').innerHTML=patternDiagram(currentBlock().pattern,currentBlock(),song)+'<small class="hint">時長皆用記譜長度的 7/8 顯示與發聲</small>'}
function practiceWindow(cursor,lead){const all=practiceEvents(),events=[];let lo=0,hi=all.length;while(lo<hi){const mid=(lo+hi)>>1;if(all[mid].t<=cursor+.001)lo=mid+1;else hi=mid}for(let i=lo-1;i>=0&&all[i].t>=cursor-64;i--)if(all[i].t+all[i].duration>cursor)events.push(all[i]);for(let i=lo;i<all.length&&all[i].t<=cursor+lead;i++)events.push(all[i]);const end=songLength();if(song.loop&&cursor+lead>=end){const from=songEngine?.from??blockStart(selected)+startOffset;for(let e of all){if(e.t<from)continue;const t=end+e.t-from;if(t>cursor+lead)break;if(t>cursor+.001)events.push({...e,t})}}return events}

const LYRICS_STORE='chord-studio-lyrics-v1',SECTION_NAMES={intro:'前奏',verse:'主歌',bridge:'橋段',chorus:'副歌',outro:'尾奏',custom:'自訂樂段'};
let lyricDoc={version:1,title:'',sections:[]},lyricStage=1,lyricArmed=null,lyricSelected=null,lyricCounter=0;
function lyricId(prefix='s'){return prefix+Date.now().toString(36)+(++lyricCounter).toString(36)}
function lyricMessage(t){$('lyricMessage').textContent=t}
function saveLyrics(){lyricDoc.title=$('lyricTitle').value;try{localStorage.setItem(LYRICS_STORE,JSON.stringify(lyricDoc))}catch(e){lyricMessage('目前瀏覽器不能自動保存，請匯出專案備份。')}updateLyricChordText()}
function validateLegacyLyrics(raw){if(!raw||raw.version!==1||!Array.isArray(raw.sections)||raw.sections.length>60)throw Error('歌詞專案格式不正確，或樂段超過 60 個。');const sections=[];let totalChars=0;for(let s of raw.sections){if(!Object.hasOwn(SECTION_NAMES,s.type)||typeof s.text!=='string'||s.text.length>30000||!Array.isArray(s.chords)||s.chords.length>1000)throw Error('某個樂段的內容不正確。');totalChars+=s.text.length;if(totalChars>100000)throw Error('歌詞內容過長。');const chords=[];for(let a of s.chords){if(!Number.isInteger(a.line)||a.line<0||a.line>1000||!Number.isInteger(a.column)||a.column<0||a.column>30000||!Number.isInteger(a.root)||a.root<0||a.root>11||!Number.isInteger(a.quality)||a.quality<0||a.quality>=qualities.length)throw Error('和弦位置或後綴資料不正確。');chords.push({id:lyricId('c'),line:a.line,column:a.column,root:a.root,quality:a.quality})}sections.push({id:lyricId(),type:s.type,label:String(s.label||SECTION_NAMES[s.type]).slice(0,60),text:s.text,chords})}return {version:1,title:String(raw.title||'').slice(0,80),sections}}
function addLyricSection(type){if(!Object.hasOwn(SECTION_NAMES,type)||lyricDoc.sections.length>=60)return;const count=lyricDoc.sections.filter(s=>s.type===type).length;lyricDoc.sections.push({id:lyricId(),type,label:SECTION_NAMES[type]+(count?' '+(count+1):''),text:'',chords:[]});renderLyricSections();saveLyrics()}
function moveLyricSection(from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=lyricDoc.sections.length||to>=lyricDoc.sections.length||from===to)return false;const s=lyricDoc.sections.splice(from,1)[0];lyricDoc.sections.splice(to,0,s);renderLyricSections();saveLyrics();return true}
function renderLyricSections(){const list=$('lyricSectionList');list.innerHTML='';lyricDoc.sections.forEach((s,i)=>{const card=document.createElement('div');card.className='section-chip';card.id='lyricSection'+i;const label=document.createElement('input');label.value=s.label;label.maxLength=60;label.setAttribute('aria-label','樂段名稱');label.oninput=()=>{s.label=label.value;saveLyrics()};const handle=document.createElement('button');handle.className='section-drag';handle.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7H19M5 12H19M5 17H19"/></svg>';handle.setAttribute('aria-label','拖曳排序 '+s.label);const resolve=(p,x,y,commit)=>{const target=document.elementFromPoint(x,y)?.closest('.section-chip');document.querySelectorAll('.bank-drop-target').forEach(n=>n.classList.remove('bank-drop-target'));if(!target)return false;target.classList.add('bank-drop-target');if(commit)moveLyricSection(p.index,Number(target.id.slice('lyricSection'.length)));return true};installPointerDrop(handle,{index:i},s.label,resolve);handle.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveLyricSection(i,i+(e.key==='ArrowLeft'?-1:1))}};const remove=document.createElement('button');remove.className='section-remove';remove.textContent='移除';remove.onclick=()=>{if((s.text||s.chords.length)&&!window.confirm('移除這個樂段及其中的歌詞、和弦？'))return;lyricDoc.sections.splice(i,1);renderLyricSections();saveLyrics()};card.append(handle);card.append(label);card.append(remove);list.append(card)});if(!lyricDoc.sections.length)list.innerHTML='<div class="empty-lyric">先加入這首歌需要的樂段。</div>'}
function setLyricStage(stage){if(stage>1&&!lyricDoc.sections.length){lyricMessage('請先加入至少一個樂段，可以只選自訂樂段。');return false}lyricStage=stage;$('lyricSetup').hidden=stage!==1;$('lyricInput').hidden=stage!==2;$('lyricCompose').hidden=stage!==3;for(let i=1;i<=3;i++)$('lyricStep'+i).classList.toggle('active',stage===i);if(stage===1)renderLyricSections();if(stage===2)renderLyricInputs();if(stage===3){refreshLyricsPalette();renderLyricCanvas()}saveLyrics();return true}
function reconcileLyricAnchors(section){const lines=section.text.split('\n');for(let a of section.chords){a.line=Math.min(a.line,lines.length-1);const limit=Math.max(16,Array.from(lines[a.line]||'').length+4);a.column=Math.min(a.column,limit)}const seen=new Map();for(let a of section.chords)seen.set(a.line+':'+a.column,a);section.chords=[...seen.values()]}
function renderLyricInputs(){const area=$('lyricTextInputs');area.innerHTML='';for(let s of lyricDoc.sections){const wrap=document.createElement('div');wrap.className='lyric-input-section';const label=document.createElement('label');label.textContent=s.label;const input=document.createElement('textarea');input.value=s.text;input.rows=s.type==='intro'||s.type==='outro'?2:5;input.maxLength=30000;input.placeholder='在這裡輸入或貼上歌詞；純樂器樂段可留白。';input.oninput=()=>{s.text=input.value;reconcileLyricAnchors(s);saveLyrics()};wrap.append(label);wrap.append(input);area.append(wrap)}}
function lyricSymbol(a){return songNames()[a.root]+qualities[a.quality][1]}
function lyricEntries(){return lyricDoc.sections.flatMap(section=>section.chords.slice().sort((a,b)=>a.line-b.line||a.column-b.column).map(chord=>({section,chord})))}
function updateLyricChordText(){if(!window.lyricsReady)return;$('lyricAllChords').value=lyricEntries().map(e=>lyricSymbol(e.chord)).join(' ')}
function refreshLyricsPalette(){if(!window.lyricsReady)return;const select=$('lyricPaletteQuality'),old=Number(select.value)||0;select.innerHTML='';qualities.forEach((q,i)=>{if(levelQualityAllowed(i))select.add(new Option((q[1]||'無後綴')+' · '+q[0],i))});select.value=levelQualityAllowed(old)?old:0;const bank=$('lyricChordBank');bank.innerHTML='';songNames().forEach((_,root)=>{const payload={kind:'new',root,quality:Number(select.value)},button=document.createElement('button');button.className='root-token';button.textContent=lyricSymbol(payload);installPointerDrop(button,payload,button.textContent,resolveLyricDrop,p=>{lyricArmed={...p};$('lyricArmed').textContent='已選 '+lyricSymbol(p)+'，點歌詞的字放置；也可以拖曳。'});bank.append(button)});updateLyricChordText()}
function placeLyricChord(sectionId,line,column,payload){const section=lyricDoc.sections.find(s=>s.id===sectionId);if(!section||!Number.isInteger(line)||!Number.isInteger(column)||line<0||column<0)return false;if(payload.kind==='move'){const source=lyricDoc.sections.find(s=>s.id===payload.sectionId),old=source?.chords.find(a=>a.id===payload.id);if(!old)return false;source.chords=source.chords.filter(a=>a.id!==payload.id);payload={...payload,root:old.root,quality:old.quality}}if(section.chords.length>=1000){lyricMessage('每個樂段最多放 1000 個和弦。');return false}const existing=section.chords.find(a=>a.line===line&&a.column===column);if(existing){existing.root=payload.root;existing.quality=payload.quality;lyricSelected={sectionId,id:existing.id}}else{const a={id:lyricId('c'),line,column,root:payload.root,quality:payload.quality};section.chords.push(a);lyricSelected={sectionId,id:a.id}}renderLyricCanvas();saveLyrics();return true}
function resolveLyricDrop(payload,x,y,commit){const cell=document.elementFromPoint(x,y)?.closest('.lyric-cell');document.querySelectorAll('.bank-drop-target').forEach(n=>n.classList.remove('bank-drop-target'));if(!cell)return false;cell.classList.add('bank-drop-target');if(commit)placeLyricChord(cell.getAttribute('data-section'),Number(cell.getAttribute('data-line')),Number(cell.getAttribute('data-column')),payload);return true}
function selectedLyricChord(){const section=lyricDoc.sections.find(s=>s.id===lyricSelected?.sectionId),chord=section?.chords.find(a=>a.id===lyricSelected?.id);return {section,chord}}
function editLegacyLyricChord(sectionId,id){lyricSelected={sectionId,id};const {chord}=selectedLyricChord();if(!chord)return;$('lyricChordEditor').hidden=false;$('lyricEditRoot').innerHTML='';songNames().forEach((n,i)=>$('lyricEditRoot').add(new Option(n,i)));$('lyricEditRoot').value=chord.root;const q=$('lyricEditQuality');q.innerHTML='';qualities.forEach((a,i)=>{if(levelQualityAllowed(i)||i===chord.quality){const o=new Option(songNames()[chord.root]+a[1]+' · '+a[0],i);o.disabled=!levelQualityAllowed(i);q.add(o)}});q.value=chord.quality}
function renderLyricCanvas(){const canvas=$('lyricCanvas');canvas.innerHTML='';for(let s of lyricDoc.sections){const section=document.createElement('section');section.className='lyric-sheet-section';const title=document.createElement('h3');title.textContent=s.label;section.append(title);const lines=s.text.split('\n');lines.forEach((line,lineIndex)=>{const row=document.createElement('div');row.className='lyric-row';const chars=Array.from(line),anchors=s.chords.filter(a=>a.line===lineIndex),maxCol=Math.max(chars.length+3,line?0:15,...anchors.map(a=>a.column+2));for(let column=0;column<=maxCol;column++){const cell=document.createElement('span');cell.className='lyric-cell';cell.setAttribute('data-section',s.id);cell.setAttribute('data-line',lineIndex);cell.setAttribute('data-column',column);cell.setAttribute('role','button');cell.tabIndex=0;const char=document.createElement('span');char.className='lyric-char';char.textContent=chars[column]??' ';cell.append(char);const anchor=anchors.find(a=>a.column===column);if(anchor){const chord=document.createElement('button');chord.className='lyric-chord';chord.textContent=lyricSymbol(anchor);const payload={kind:'move',sectionId:s.id,id:anchor.id};installPointerDrop(chord,payload,chord.textContent,resolveLyricDrop,()=>editLyricChord(s.id,anchor.id));cell.append(chord)}const place=()=>{if(lyricArmed)placeLyricChord(s.id,lineIndex,column,lyricArmed);else if(anchor)editLyricChord(s.id,anchor.id);else lyricMessage('先選一個和弦，再點文字放置，或直接拖曳。')};cell.onclick=e=>{if(e.target.closest?.('.lyric-chord'))return;place()};cell.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();place()}};row.append(cell)}section.append(row)});canvas.append(section)}updateLyricChordText()}
function lyricTextWidth(text){return Array.from(text).reduce((n,ch)=>n+(ch.codePointAt(0)>0x2ff?2:1),0)}
function lyricPlainText(){const parts=[lyricDoc.title||'歌詞和弦譜',''];for(let s of lyricDoc.sections){parts.push('【'+s.label+'】');s.text.split('\n').forEach((line,i)=>{const chars=Array.from(line),anchors=s.chords.filter(a=>a.line===i).sort((a,b)=>a.column-b.column);let top='';for(let a of anchors){const width=lyricTextWidth(chars.slice(0,a.column).join(''))+Math.max(0,a.column-chars.length),start=Math.max(width,top.length?top.length+1:0);top+=' '.repeat(Math.max(0,start-top.length))+lyricSymbol(a)}if(top)parts.push(top);parts.push(line)});parts.push('')}return parts.join('\n')}
function lyricChartHtml(){let body='<h1>'+safeText(lyricDoc.title||'歌詞和弦譜')+'</h1>';for(let s of lyricDoc.sections){body+='<section><h2>'+safeText(s.label)+'</h2>';s.text.split('\n').forEach((line,i)=>{const chars=Array.from(line),anchors=s.chords.filter(a=>a.line===i),last=Math.max(chars.length-1,0,...anchors.map(a=>a.column));body+='<div class="line">';for(let column=0;column<=last;column++){const a=anchors.find(a=>a.column===column);body+='<span class="cell">'+(a?'<b>'+safeText(lyricSymbol(a))+'</b>':'')+'<span>'+safeText(chars[column]??' ')+'</span></span>'}body+='</div>'});body+='</section>'}return '<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+safeText(lyricDoc.title||'歌詞和弦譜')+'</title><style>body{font-family:system-ui,sans-serif;margin:40px auto;padding:0 25px;max-width:900px;color:#233c32}h1{font-size:25px}h2{font-size:15px;color:#64816e;margin:24px 0 8px}.line{line-height:1.7}.cell{display:inline-flex;position:relative;min-width:.65em;height:55px;padding-top:27px;box-sizing:border-box;vertical-align:top;white-space:pre;font-size:17px}.cell b{position:absolute;top:1px;left:0;font:600 13px system-ui;white-space:nowrap;color:#285e4f}@media print{body{margin:0;max-width:none}section{break-inside:avoid}}</style><body>'+body+'</body></html>'}
async function copyAllLyricChords(){const text=lyricEntries().map(e=>lyricSymbol(e.chord)).join(' ');if(!text){lyricMessage('先放上至少一個和弦。');return}try{if(!navigator.clipboard?.writeText)throw Error('clipboard');await navigator.clipboard.writeText(text);lyricMessage('全部和弦已複製，可貼到第二頁的文字和弦區。')}catch(e){$('lyricAllChords').focus();$('lyricAllChords').select();let copied=false;try{copied=document.execCommand('copy')}catch(e){}lyricMessage(copied?'全部和弦已複製。':'已選取全部和弦，請使用裝置的「拷貝」。')}}
function sendLyricsToSong(){const text=lyricEntries().map(e=>lyricSymbol(e.chord)).join(' ');if(!text){lyricMessage('先放上至少一個和弦。');return false}try{addTextChords(text);switchWorkspace('song');openBasicEditor();songMessage('歌詞和弦已加入結尾，請在此設定拍長與演奏方式。');return true}catch(e){lyricMessage(e.message);return false}}
function switchWorkspace(mode){stop();$('learnWorkspace').hidden=mode!=='learn';$('songWorkspace').hidden=mode!=='song';$('lyricsWorkspace').hidden=mode!=='lyrics';for(let key of ['learn','song','lyrics']){const button=$(key==='lyrics'?'lyricsMode':key+'Mode');button.classList.toggle('active',mode===key);button.setAttribute('aria-selected',mode===key?'true':'false')}if(mode==='song')renderSong();if(mode==='lyrics')setLyricStage(lyricStage)}
