function ensureLyricLine(section,line){section.layout??=[];const text=section.text.split('\n')[line]||'',chars=Array.from(text),defaults=defaultWordPositions(text);let row=section.layout[line];if(!row||!Array.isArray(row.words))row=section.layout[line]={words:defaults,width:24};if(row.words.length!==defaults.length)row.words=defaults.map((x,i)=>Number.isFinite(row.words[i])?row.words[i]:x);row.words=row.words.map(x=>Math.max(0,Math.min(LYRIC_LIMIT-6,x)));const end=Math.max(0,...row.words.map((x,i)=>x+lyricAdvance(chars[i])));row.width=Math.max(24,end+5,Number.isFinite(row.width)?Math.min(LYRIC_LIMIT,row.width):24,...section.chords.filter(a=>a.line===line).map(a=>Number.isFinite(a.x)?a.x+4:0));return row}
