 Array.from(line).forEach((char,index)=>{const word=document.createElement(lyricMoveWords?'button':'span');word.className='lyric-free-word';word.textContent=char;word.style.left=layout.words[index]*LYRIC_UNIT+'px';word.style.width=lyricAdvance(char)*LYRIC_UNIT+'px';if(lyricMoveWords){word.setAttribute('aria-label','左右移動歌詞「'+char+'」，也可用左右方向鍵');const payload={kind:'word',sectionId:section.id,line:lineIndex,index,char};installPointerDrop(word,payload,char,resolveWordDrop);word.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveLyricWord(section.id,lineIndex,index,layout.words[index]+(e.key==='ArrowLeft'?-.125:.125))}}}row.append(word)});
