function missionTextName(pc,mode=$('noteDisplay').value){pc=(pc+12)%12;const nums=['1','♯1／♭2','2','♯2／♭3','3','4','♯4／♭5','5','♯5／♭6','6','♯6／♭7','7'];return mode==='numeral'?nums[pc]:songNames()[pc]}
function missionChordLabel(root,quality){return songNames()[root%12]+qualities[quality][1]}
function missionKeyNotes(root,quality){return [...new Set(qualities[quality][2].map(i=>(root+i)%12))]}
function missionAudioChord(root,quality){const notes=missionKeyNotes(root,quality).map(pc=>60+pc);missionSymbols.length;return audio().then(()=>{const start=context.currentTime+.04;notes.forEach((n,i)=>tone(n,.85,start+i*.012,.61))}).catch(e=>{$('status').textContent=e.name==='PlaybackCancelled'?'已取消播放，繼續收音。':'音訊尚未就緒，請再按一次重播。'})}
function setMissionTab(kind){missionKind=kind;document.querySelectorAll('.mission-tab').forEach(b=>{const active=b.getAttribute('data-mission')===kind;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false')});for(let k of ['build','ear','mic','read'])$('mission-'+k).hidden=k!==kind;if(micStream&&kind!=='mic'&&kind!=='read')stopChordMic();if(micStream&&kind==='mic'&&micTask?.kind==='read')stopChordMic();if(micStream&&kind==='read'&&micTask?.kind!=='read')stopChordMic();if(kind==='read'&&!readTask)makeSightRead();if(kind==='mic'&&!micTask)newMicChord()}
function makeBuildTask(){const root=missionRandom(missionRoots),spec=missionRandom(missionSymbols),roleIndex=Math.floor(Math.random()*spec.degree.length),semitone=qualities[spec.q][2][roleIndex];return {root,q:spec.q,roleIndex,expected:(root+semitone)%12,step:0}}
function buildDistractors(task){const out=new Set([task.expected]);while(out.size<4)out.add(Math.floor(Math.random()*12));const values=[...out];for(let i=values.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]]}return values}
function renderBuildChoices(){const area=$('buildChoices');area.innerHTML='';if(!buildTask)return;for(let pc of buildDistractors(buildTask)){const b=document.createElement('button');b.className='mission-choice';b.textContent=missionTextName(pc);b.onclick=()=>answerBuild(pc,b);area.append(b)}}
function startBuildTask(){stop();buildTask=makeBuildTask();$('buildChord').hidden=true;$('buildProgress').textContent='聽辨 '+missionChordLabel(buildTask.root,buildTask.q)+' · 和弦組成音';const spec=missionSymbols.find(s=>s.q===buildTask.q),degree=spec.degree[buildTask.roleIndex];$('buildPrompt').textContent='找出和弦的「'+degree+'」音。聽完後選一個音。';$('buildChord').textContent=missionChordLabel(buildTask.root,buildTask.q);$('buildChoices').innerHTML='';$('buildReplay').disabled=false;$('buildReveal').hidden=false;$('buildFeedback').textContent='';missionAudioChord(buildTask.root,buildTask.q);renderBuildChoices()}
function answerBuild(pc,button){if(!buildTask)return;const expected=buildTask.expected;if(pc!==expected){button.classList.add('wrong');$('buildFeedback').textContent='這個音不太一樣，再聽一次和弦，試著數半音或用簡譜找。';return}button.classList.add('correct');for(let b of $('buildChoices').children)b.disabled=true;const spec=missionSymbols.find(s=>s.q===buildTask.q);$('buildFeedback').textContent='答對了！'+missionTextName(pc)+' 是和弦中的 '+spec.degree[buildTask.roleIndex]+' 音。';$('buildProgress').textContent='完成一個和弦音';$('buildPrompt').textContent='想繼續就再按「開始拼圖」';$('buildStart').textContent='下一個音';$('buildStart').onclick=startBuildTask}
function startEarTask(){earTask={root:missionRandom(missionRoots),spec:missionRandom(missionSymbols),done:false};$('earProgress').textContent='聽辨和弦品質';$('earPrompt').textContent='這個和弦聽起來屬於哪一種？';$('earAnswer').hidden=true;$('earChoices').innerHTML='';$('earReplay').disabled=false;$('earReveal').hidden=false;$('earFeedback').textContent='';for(let spec of missionSymbols){const b=document.createElement('button');b.className='mission-choice';b.textContent=spec.name;b.onclick=()=>answerEar(spec.q,b);$('earChoices').append(b)}playEarTask()}
function playEarTask(){if(earTask)missionAudioChord(earTask.root,earTask.spec.q)}
function answerEar(q,button){if(!earTask)return;if(q===earTask.spec.q){earTask.done=true;button.classList.add('correct');$('earAnswer').hidden=false;$('earAnswer').textContent=missionChordLabel(earTask.root,q)+' · '+earTask.spec.name;$('earFeedback').textContent='答對了！'+(q===1?'小三和弦的三音比大三和弦低半音。':q===7?'大七和弦比屬七多了大七音。':q===6?'屬七和弦有向主和弦解決的張力。':'大三和弦可留意明亮、穩定的聲響。');for(let b of $('earChoices').children)b.disabled=true}else{$('earFeedback').textContent='再聽一次，留意三音和七音的差別。';button.classList.add('wrong')}}
function readProgressionTemplates(){return [{name:'四和弦流行循環',d:[0,4,5,3]},{name:'小調起始循環',d:[5,3,0,4]},{name:'五〇年代四和弦',d:[0,5,3,4]},{name:'主下屬屬和弦',d:[0,3,4,3]},{name:'ii–V–I 終止型',d:[1,4,0,0]},{name:'八小節流行進行',d:[0,4,5,3,0,4,3,4]},{name:'下行感循環',d:[5,4,3,0]}]}
function makeSightRead(){stop();const key=$('readKey').value,tonic=key==='random'?Math.floor(Math.random()*12):Number(key),pattern=missionRandom(readProgressionTemplates()),scale=[0,2,4,5,7,9,11];readTask={tonic,template:pattern,chords:pattern.d.map((degree,i)=>{const root=(tonic+scale[degree])%12,q=degree===1||degree===2||degree===5?1:degree===4&&Math.random()<.35?6:degree===0&&Math.random()<.2?7:0;return {root,q,symbol:missionChordLabel(root,q),roman:['I','ii','iii','IV','V','vi','vii°'][degree]}})};readIndex=0;showReadDegrees=false;$('readDegrees').setAttribute('aria-pressed','false');$('readDegrees').textContent='顯示級數';$('readPattern').innerHTML='';readTask.chords.forEach((chord,i)=>{const box=document.createElement('div');box.className='read-chord'+(i===0?' current':'');box.id='readChord'+i;box.innerHTML='<em>'+(i+1)+'</em><b>'+chord.symbol+'</b><small id="readDegree'+i+'" '+(showReadDegrees?'':'hidden')+'>'+chord.roman+'</small>';$('readPattern').append(box)});$('readProgress').textContent=readTask.template.name+' · '+songNames()[tonic]+' 大調 · 每格四拍';$('readPlay').disabled=false;$('readDegrees').disabled=false;$('readPrevious').disabled=true;$('readNext').disabled=false;$('readCurrent').textContent='第 1 格：'+readTask.chords[0].symbol+'；先在鋼琴上試彈。';$('readFeedback').textContent='';updateSightRead()}
function updateSightRead(){if(!readTask)return;for(let i=0;i<readTask.chords.length;i++){$('readChord'+i).classList.toggle('current',i===readIndex);$('readChord'+i).classList.toggle('done',i<readIndex)}const done=readIndex>=readTask.chords.length;$('readPrevious').disabled=done||readIndex===0;$('readNext').disabled=done;$('readNext').textContent=done?'完成！再抽一題':'我彈好了・下一格';$('readCurrent').textContent=done?'這張和弦譜讀完了！':'第 '+(readIndex+1)+' 格：'+readTask.chords[readIndex].symbol+'；每格四拍。';$('readProgress').textContent=done?readTask.template.name+' · 完成':readTask.template.name+' · '+(readIndex+1)+' / '+readTask.chords.length+' 格';if(micTask?.kind==='read'){if(done){micTask=null;micObserved.clear();renderMicNotes()}else micSetTarget(readTask.chords[readIndex])}const checking=!!micStream&&micTask?.kind==='read'&&!done;$('readNext').hidden=checking;$('readMicCheck').hidden=!checking;$('readMicStop').hidden=!checking;$('readMicStart').hidden=checking}
function nextReadChord(delta){if(!readTask)return;if(readIndex>=readTask.chords.length){makeSightRead();return}readIndex=Math.max(0,Math.min(readTask.chords.length,readIndex+delta));$('readFeedback').textContent='';updateSightRead()}
function toggleReadDegrees(){showReadDegrees=!showReadDegrees;$('readDegrees').setAttribute('aria-pressed',showReadDegrees?'true':'false');$('readDegrees').textContent=showReadDegrees?'隱藏級數':'顯示級數';if(readTask)readTask.chords.forEach((c,i)=>{$('readDegree'+i).hidden=!showReadDegrees})}
async function playReadDemo(){if(!readTask)return;stop();try{await audio();const bpm=Math.max(30,Math.min(200,Number($('tempo').value)||76)),unit=60/bpm,start=context.currentTime+.08;readTask.chords.forEach((chord,i)=>{const notes=missionKeyNotes(chord.root,chord.q).map(pc=>60+pc);notes.forEach(n=>tone(n,unit*3.5,start+i*unit*4,.55))})}catch(e){$('readFeedback').textContent='音訊還沒準備好，請再試一次。'}}
function newMicChord(){const root=missionRandom(missionRoots),spec=missionRandom(missionSymbols);return {root,q:spec.q,classes:missionKeyNotes(root,spec.q),kind:'chord'}}
function micSetTarget(chord){micTask=chord?{...chord,kind:'read'}:newMicChord();micObserved.clear();renderMicNotes();if(micTask.kind==='read'){$('micPrompt').textContent='目前和弦：'+missionChordLabel(micTask.root,micTask.q)+'。請彈奏，再按「檢查目前和弦」。';$('micCheck').hidden=true;$('micNext').hidden=true;$('readMicCheck').hidden=!micStream;$('readNext').hidden=!!micStream}else{$('micPrompt').textContent='請在鋼琴上彈出 '+missionChordLabel(micTask.root,micTask.q)+'；可同時按下或分開彈。';$('micCheck').hidden=false;$('micNext').hidden=false;$('readMicCheck').hidden=true;$('readNext').hidden=false;$('micAnswer').hidden=true}$('micFeedback').textContent='';$('micProgress').textContent=micStream?'收音中・音訊只在本機即時分析':'準備好時按「開始收音練習」'}
