function startChordMic(){if(micStream){$('micFeedback').textContent='收音已經開啟；彈出目前和弦後按檢查。';return}if(!window.isSecureContext){$('micFeedback').textContent='麥克風需要安全連線，請從 HTTPS 網站開啟本頁。';return}if(!navigator.mediaDevices?.getUserMedia){$('micFeedback').textContent='目前瀏覽器沒有可用的麥克風介面，請用 iPad Safari 開啟 HTTPS 網站。';return}const requestEpoch=++micRequestEpoch;let request;try{request=navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false})}catch(e){$('micFeedback').textContent='無法開啟麥克風：'+e.message;return}$('micFeedback').textContent='等待你允許瀏覽器使用麥克風…';request.then(stream=>{if(requestEpoch!==micRequestEpoch){stream.getTracks().forEach(t=>t.stop());return}micStream=stream;return baseAudio().then(()=>{micAnalyser=context.createAnalyser();micAnalyser.fftSize=8192;micAnalyser.smoothingTimeConstant=.18;micFrames=new Float32Array(micAnalyser.frequencyBinCount);const input=context.createMediaStreamSource(stream);input.connect(micAnalyser);micInput=input;$('micStart').disabled=true;$('micStop').disabled=false;$('micFeedback').textContent='已開始聽音。請直接在附近的鋼琴上彈；不需要按網頁鍵盤。';$('micProgress').textContent='收音中・音訊只在本機即時分析';if(micTask?.kind==='read')$('readMicCheck').hidden=false;else if(micTask?.kind==='chord')$('micNext').hidden=false;updateSightRead();micScan()})}).catch(e=>{$('micFeedback').textContent=e.name==='NotAllowedError'?'麥克風權限未開啟；可在 iPad Safari 的網站設定中允許麥克風。':'無法開啟麥克風：'+e.message})}
let micInput=null,micRequestEpoch=0;
function stopChordMic(){micRequestEpoch++;if(micRAF)cancelAnimationFrame(micRAF);micRAF=0;try{micStream?.getTracks().forEach(t=>t.stop());micInput?.disconnect();micAnalyser?.disconnect()}catch(e){}micStream=null;micInput=null;micAnalyser=null;micFrames=null;micObserved.clear();if(window._tasksReady){$('micStart').disabled=false;$('micStop').disabled=true;$('micCheck').hidden=true;$('micProgress').textContent='麥克風尚未啟用';renderMicNotes();if($('readMicStatus'))$('readMicStatus').textContent='收音已停止；可以自行練習，或再開啟檢查。';if($('readMicStart'))$('readMicStart').hidden=false;if($('readMicStop'))$('readMicStop').hidden=true;if($('readMicCheck'))$('readMicCheck').hidden=true;if($('readNext'))$('readNext').hidden=false}}
function analyzePitchNotes(){micAnalyser.getFloatFrequencyData(micFrames);const sampleRate=context.sampleRate,bin=sampleRate/micAnalyser.fftSize,peaks=[],low=Math.max(2,Math.floor(48/bin)),high=Math.min(micFrames.length-2,Math.floor(1600/bin));let max=-120;for(let i=low;i<=high;i++)max=Math.max(max,micFrames[i]);if(max<-88)return [];for(let i=low+1;i<high;i++){const db=micFrames[i];if(db<Math.max(-89,max-50)||db<micFrames[i-1]||db<micFrames[i+1])continue;const offset=.5*(micFrames[i-1]-micFrames[i+1])/(micFrames[i-1]-2*db+micFrames[i+1]||1),freq=(i+Math.max(-.5,Math.min(.5,offset)))*bin,midi=69+12*Math.log2(freq/440),note=Math.round(midi);if(note<31||note>94||Math.abs(midi-note)>.49)continue;peaks.push({freq,note,db})}peaks.sort((a,b)=>a.freq-b.freq);const kept=[];for(const peak of peaks){let harmonic=false;for(const lower of kept){const ratio=peak.freq/lower.freq,integer=Math.round(ratio),tolerance=Math.max(.035,integer*.012);if(integer>=2&&integer<=10&&Math.abs(ratio-integer)<tolerance&&lower.db>=peak.db-18){harmonic=true;break}}if(!harmonic)kept.push(peak)}const byNote=new Map();for(const peak of kept){const old=byNote.get(peak.note);if(!old||old.db<peak.db)byNote.set(peak.note,peak)}return [...byNote.keys()]}
function analyzePitches(){return [...new Set(analyzePitchNotes().map(n=>(n%12+12)%12))]}
function micScan(){if(!micStream||!micAnalyser)return;const now=performance.now();for(let pc of analyzePitches())micObserved.set(pc,now);for(let [pc,t]of micObserved)if(now-t>6000)micObserved.delete(pc);renderMicNotes();if(micTask?.kind==='read')$('readMicStatus').textContent='即時聽到：'+[...micObserved.keys()].map(pc=>missionTextName(pc)).join(' · ')+'；彈好後可核對。';micRAF=requestAnimationFrame(micScan)}
function checkMicChord(){if(readTask&&readIndex<readTask.chords.length&&document.getElementById('readMicCheck')&&!$('readMicCheck').hidden&&micTask?.kind==='read'){}else if(!micStream||!micTask){if(readTask&&readIndex<readTask.chords.length){$('readFeedback').textContent='先在視譜題啟用收音檢查，或自行彈完後按下一格。'}else $('micFeedback').textContent='先開始收音練習。';return false}const missing=micTask.classes.filter(pc=>!micObserved.has(pc));if(missing.length){$('micFeedback').textContent='目前還沒聽到 '+missing.map(pc=>missionTextName(pc)).join('、')+'；可以先彈單音測試，再把和弦音一起彈出。';return false}if(micTask.kind==='read'){const chord=readTask?.chords[readIndex];nextReadChord(1);$('readFeedback').textContent='音高集合符合 '+missionChordLabel(chord.root,chord.q)+'，讀對了！';$('readMicStatus').textContent=readIndex>=readTask.chords.length?'麥克風檢查完成！': '已核對 '+missionChordLabel(chord.root,chord.q)+'，下一格：'+missionChordLabel(readTask.chords[readIndex].root,readTask.chords[readIndex].q);return true}$('micAnswer').hidden=false;$('micAnswer').textContent=missionChordLabel(micTask.root,micTask.q)+' · 組成音都聽到了';$('micFeedback').textContent='找到了！可以比較各音在不同音域的音色，再按下一個和弦。';return true}
function nextMicChord(){if(!micStream){$('micFeedback').textContent='先開啟收音。';return}micSetTarget(null);$('micFeedback').textContent='新的和弦準備好了，請彈奏。'}
