let sightSequence=null,sightIndex=0,sightSelected=new Set(),globalMicButton=null,buildMicReadyAt=0,virtualPianoNotes=new Set(),chordFinder=null,finderPreviousMicNotes=new Set(),finderNoteCooldown=new Map(),sightCheckPassed=false,micObservedNotes=new Map();
let singleMicCandidate=null,singleMicCount=0,singleMicSilence=0,singleMicLatched=null,lastSingleMicScan=0,singleMicPitch=null,finderTaskNumber=0,buildTaskNumber=0;
function sightName(pc){return missionTextName((pc+12)%12)}
function sightChordName(ch){let label=missionChordLabel(ch.root,ch.q);if(ch.inv){const tones=qualities[ch.q][2],bass=(ch.root+tones[ch.inv%tones.length])%12;label+='/'+songNames()[bass]}return label}
function missionQualityPool(){const level=currentLevel();if(level==='beginner')return [0,1,6,7];if(level==='intermediate')return qualities.map((_,i)=>i).filter(i=>levelQualityAllowed(i));return qualities.map((_,i)=>i)}
function beginnerChordBank(){const scale=[0,2,4,5,7,9,11],bank=[];for(const tonic of [0,7,5]){const pcs=new Set(scale.map(n=>(tonic+n)%12));for(const root of pcs)for(const q of [0,1,6,7])if(qualities[q][2].every(n=>pcs.has((root+n)%12)))bank.push({root,q,tonic})}return bank}
function missionRootPool(){return currentLevel()==='beginner'?[...new Set(beginnerChordBank().map(ch=>ch.root))]:Array.from({length:12},(_,i)=>i)}
function randomMissionChord(){return currentLevel()==='beginner'?missionRandom(beginnerChordBank()):{root:missionRandom(missionRootPool()),q:missionRandom(missionQualityPool())}}
function missionQualityName(q){return missionSymbols.find(s=>s.q===q)?.name||qualities[q][1]}
