function refreshPracticeDifficulty(){const level=currentLevel(),copy={beginner:['初階任務','根音與基本和弦','以 C、G、F 調常見進行為主；和弦拼圖與聽辨限定大三、小三、屬七、大七，隨機和弦譜不含轉位。'],intermediate:['中階任務','擴展和弦與轉位','加入更多調性、常見後綴與轉位；循序練聽、找音和讀和弦譜。'],advanced:['進階任務','完整和弦與轉位','開放所有和弦種類、根音與轉位；隨機譜會混合更多聲部配置。']}[level];$('practiceLevelChip').textContent=copy[0];$('practiceLevelDescription').textContent=copy[1];$('sightLevelTip').textContent=copy[2];$('buildInstruction').textContent=level==='beginner'?'只會使用大三、小三、屬七、大七和弦；聽完和弦後找出指定構成音。可選答案、點琴鍵或開啟收音彈單音。':level==='intermediate'?'題目會加入不同調性與常見後綴；聽完和弦後找指定構成音，也可用琴鍵或收音作答。':'題目可能使用完整和弦種類與延伸音；聽完和弦後找出指定構成音。';$('earInstruction').textContent='聽完後辨認和弦種類；目前難度可用和弦：'+missionQualityPool().map(missionQualityName).join('、')+'。';$('micInstruction').textContent='依序彈出目前在「和弦探索」選定的和弦音。收音找音時一次彈一個音，聽到正確基音後再放開、彈下一音；和弦譜核對則可同時彈出多個音。';$('readInstruction').textContent=copy[2]+' 抽題後可逐格彈奏，收音或琴鍵答案會用同一套檢查。'}
function makeBuildTask(){const {root,q}=randomMissionChord(),tones=qualities[q][2],roleIndex=Math.floor(Math.random()*tones.length);return {root,q,roleIndex,expected:(root+tones[roleIndex])%12,step:0}}
function startBuildTask(){stop();buildTask=makeBuildTask();buildTaskNumber++;micObserved.clear();micObservedNotes.clear();buildMicReadyAt=performance.now()+1100;const interval=qualities[buildTask.q][2][buildTask.roleIndex],role=interval===0?'根音':interval===3||interval===4?'三音':interval===6||interval===7?'五音':interval===10||interval===11?'七音':interval===13||interval===14||interval===15?'九音':interval===17||interval===18?'十一音':interval===20||interval===21?'十三音':interval===8?'五音':interval===9?'六音':interval===2?'二音':interval===5?'四音':'和弦音';$('buildChord').hidden=true;$('buildProgress').textContent='';$('buildProgress').hidden=true;$('buildPrompt').textContent=missionChordLabel(buildTask.root,buildTask.q)+' 的'+role;$('buildChord').textContent=missionChordLabel(buildTask.root,buildTask.q);$('buildChoices').innerHTML='';$('buildReplay').disabled=false;$('buildReveal').hidden=false;$('buildFeedback').textContent='';$('buildStart').textContent='下一題';$('buildStart').onclick=startBuildTask;missionAudioChord(buildTask.root,buildTask.q);renderBuildChoices();renderMicNotes()}
function answerBuild(pc,button){if(!buildTask)return;pc=(pc+12)%12;if(pc!==buildTask.expected){button?.classList.add('wrong');$('buildFeedback').textContent='答錯了，再試一次。';return}buildTask.done=true;button?.classList.add('correct');for(let b of $('buildChoices').children)b.disabled=true;for(let key of $('sightKeyboard').querySelectorAll?.('button')||[])if(Number(key.dataset.note)%12===pc)key.classList.add('selected');$('buildFeedback').textContent='答對了！'+missionTextName(pc)+' 是 '+missionDegreeLabel(buildTask.q,buildTask.roleIndex)+' 音。';$('buildProgress').textContent='完成一題';$('buildPrompt').textContent='準備好後可再做一題。'}
function startEarTask(){const chosen=randomMissionChord();earTask={root:chosen.root,spec:missionSpec(chosen.q),done:false};$('earProgress').textContent='聽辨和弦品質';$('earPrompt').textContent='這個和弦聽起來屬於哪一種？';$('earAnswer').hidden=true;$('earChoices').innerHTML='';$('earReplay').disabled=false;$('earReveal').hidden=false;$('earFeedback').textContent='';for(let q of missionQualityPool()){const b=document.createElement('button');b.className='mission-choice';b.textContent=missionQualityName(q);b.onclick=()=>answerEar(q,b);$('earChoices').append(b)}playEarTask()}
function playEarTask(){if(earTask)missionAudioChord(earTask.root,earTask.spec.q)}
function sightProgressionTemplates(){return [
 {name:'流行四和弦',d:[0,4,5,3]}, {name:'小調起始循環',d:[5,3,0,4]}, {name:'主下屬屬和弦',d:[0,3,4,3]}, {name:'I–vi–IV–V',d:[0,5,3,4]}, {name:'八小節流行進行',d:[0,4,5,3,0,4,3,4]}, {name:'ii–V–I 終止型',d:[1,4,0,0]}
]}
function makeSightSequence(){const level=currentLevel(),len=Number($('sightLength').value)||4,keys=level==='beginner'?[0,7,5]:null,tonic=keys?missionRandom(keys):Math.floor(Math.random()*12),pattern=missionRandom(sightProgressionTemplates()),scale=[0,2,4,5,7,9,11],n=len===8?8:4,pool=missionQualityPool();let chords=Array.from({length:n},(_,i)=>{const degree=pattern.d[i%pattern.d.length],root=(tonic+scale[degree])%12;let q;if(level==='beginner'){q=degree===1||degree===2||degree===5?1:0;if(degree===4&&Math.random()<.35)q=6;if((degree===0||degree===3)&&Math.random()<.35)q=7;}else q=missionRandom(pool);if(degree===6&&level==='beginner')q=0;const inv=level==='beginner'?0:Math.floor(Math.random()*Math.max(1,Math.min(qualities[q][2].length,level==='intermediate'?3:qualities[q][2].length)));return {root,q,inv,roman:['I','ii','iii','IV','V','vi','vii°'][degree]}});if(level==='advanced'&&Math.random()<.35)chords=chords.map(ch=>Math.random()<.25?{...ch,root:Math.floor(Math.random()*12)}:ch);sightSequence={level,tonic,template:pattern,chords};sightIndex=0;sightCheckPassed=false;sightSelected.clear();micObserved.clear();micObservedNotes.clear();renderSightSequence();renderSightKeyboard();$('sightDemo').disabled=false;$('sightSelfNext').disabled=false;$('sightCheck').disabled=!micStream;$('sightNext').hidden=!micStream;$('sightNext').disabled=true;updateSightTurn();$('sightStatus').textContent='試著彈出目前和弦的構成音；可分解彈或一起彈，再檢查音名與低音位置。';syncPracticeMicState()}
function renderSightSequence(){const area=$('sightProgression');area.innerHTML='';if(!sightSequence)return;sightSequence.chords.forEach((ch,i)=>{const el=document.createElement('div');el.className='sight-chord'+(i===0?' current':'');el.id='sightChord'+i;el.innerHTML='<em>'+(i+1)+' · 四拍</em><b>'+sightChordName(ch)+'</b><small>'+ch.roman+(ch.inv?' · 轉位':'')+'</small>';area.append(el)})}
function updateSightTurn(){if(!sightSequence)return;const done=sightIndex>=sightSequence.chords.length;for(let i=0;i<sightSequence.chords.length;i++){$('sightChord'+i).classList.toggle('current',i===sightIndex);$('sightChord'+i).classList.toggle('done',i<sightIndex)}$('sightCounter').textContent=done?'全部完成':`第 ${sightIndex+1} / ${sightSequence.chords.length} 格`;$('sightPrompt').textContent=done?'太好了，這組進行完成！':'目前和弦：'+sightChordName(sightSequence.chords[sightIndex])+' · 四拍';$('sightCheck').disabled=done||(!micStream&&!sightSelected.size);$('sightNext').disabled=done||!sightCheckPassed;$('sightSelfNext').disabled=done;$('sightCheck').hidden=done;$('sightNext').hidden=done||!micStream}
function renderSightKeyboard(){const host=$('sightKeyboard');if(host.dataset.ready)return;host.dataset.ready='1';const whites=[],midiStart=48,midiEnd=72;for(let n=midiStart;n<=midiEnd;n++){const pc=n%12;if([0,2,4,5,7,9,11].includes(pc)){const b=document.createElement('button');b.className='sight-key-white';b.dataset.note=n;b.textContent=sightName(pc);b.setAttribute('aria-label',sightName(pc)+' '+(Math.floor(n/12)-1)+'八度');b.onclick=()=>toggleSightNote(n,b);host.append(b);whites.push({n,el:b})}}
 for(let n=midiStart;n<=midiEnd;n++){const pc=n%12;if([1,3,6,8,10].includes(pc)){const left=whites.filter(w=>w.n<n).length;const b=document.createElement('button');b.className='sight-key-black';b.dataset.note=n;b.style.left=`${left/whites.length*100}%`;b.textContent=sightName(pc);b.setAttribute('aria-label',sightName(pc)+' 黑鍵');b.onclick=()=>toggleSightNote(n,b);host.append(b)}}}
function toggleSightNote(n,b){if(sightSelected.has(n))sightSelected.delete(n);else sightSelected.add(n);b.classList.toggle('selected',sightSelected.has(n));audio().then(()=>tone(n,.45,context.currentTime,.55)).catch(()=>{});if(chordFinder&&missionKind==='mic')chordFinderInput(n%12,'keyboard');else if(missionKind==='build'&&buildTask&&!buildTask.done)answerBuild(n%12,null);updateSightTurn()}
function sightExpected(){const ch=sightSequence?.chords[sightIndex];if(!ch)return null;const tones=qualities[ch.q][2],pcs=[...new Set(tones.map(i=>(ch.root+i)%12))],bass=(ch.root+tones[ch.inv%tones.length])%12;return {pcs,bass}}
function checkSightAnswer(){if(!sightSequence||sightIndex>=sightSequence.chords.length)return;const exp=sightExpected(),notes=[...new Set([...micObservedNotes.keys(),...sightSelected])],inputPcs=[...new Set([...micObserved.keys(),...notes.map(n=>n%12)])],missing=exp.pcs.filter(pc=>!inputPcs.includes(pc)),extras=inputPcs.filter(pc=>!exp.pcs.includes(pc));if(missing.length){$('sightStatus').textContent='還沒聽齊 '+missing.map(sightName).join('、')+'；可用不同音域或轉位重彈，再按檢查。';return false}if(extras.length){$('sightStatus').textContent='聽到非和弦音 '+extras.map(sightName).join('、')+'；請清除或重彈和弦後再檢查。';return false}if(notes.length){const bass=notes.reduce((a,b)=>a<b?a:b)%12;if(bass!==exp.bass){$('sightStatus').textContent='和弦音都找到了；目前最低音是 '+sightName(bass)+'，這格需要 '+sightName(exp.bass)+' 作低音。可換一個轉位或把低音移到左手。';return false}const span=Math.max(...notes)-Math.min(...notes);if(span>36){$('sightStatus').textContent='和弦音正確，但音域太分散；試著把最高音和最低音控制在三個八度內。';return false}}const ch=sightSequence.chords[sightIndex];$('sightStatus').textContent='和弦音與低音位置符合 '+sightChordName(ch)+'；這個和弦可用不同音域、重複音或排列方式演奏。';sightCheckPassed=true;$('sightNext').disabled=false;$('sightNext').hidden=!micStream;$('sightCheck').disabled=true;return true}
function advanceSight(){if(!sightSequence)return;sightIndex++;sightCheckPassed=false;sightSelected.clear();micObserved.clear();micObservedNotes.clear();document.querySelectorAll('.sight-keyboard button').forEach(b=>b.classList.remove('selected'));$('sightStatus').textContent='下一格準備好了。';updateSightTurn();syncPracticeMicState()}
async function playSightDemo(){if(!sightSequence)return;try{await audio();const beat=60/Math.max(40,Number($('tempo').value)||76),start=context.currentTime+.08;sightSequence.chords.forEach((ch,i)=>{const notes=qualities[ch.q][2].map(x=>60+(ch.root+x)%12);notes.forEach((n,j)=>tone(n,beat*3.55,start+i*beat*4+j*.012,.48))})}catch(e){$('sightStatus').textContent='音訊尚未準備好，請再按一次播放。'}}
let stableMicFrames=new Map(),previousMicNotes=new Set(),micTimeFrames=null,micInputDb=-120;
function refreshGlobalMicUi(){if(!globalMicButton)return;globalMicButton.classList.toggle('on',!!micStream);globalMicButton.setAttribute('aria-pressed',micStream?'true':'false');const label=globalMicButton.querySelector?.('.global-mic-label');if(label)label.textContent=micStream?'收音中・點此停止':'麥克風收音';$('micLiveStrip').classList.toggle('visible',!!micStream);const heard=micObserved.size?[...micObserved.keys()].map(sightName).join(' · '):'尚未辨識音高';$('micLiveStrip').textContent=micStream?'全站收音中 · 麥克風音量 '+(micInputDb>-58?'有收到聲音':'偏安靜')+' · 即時音高：'+heard+' · 音訊只在本機分析':'收音關閉'}
function syncPracticeMicState(){const names=[...micObserved.keys()].map(sightName);if($('sightMicState')){$('sightMicState').textContent=micStream?(names.length?'收音中・已辨識：'+names.join('、'):'收音中・等待鋼琴發聲；請保持此頁開啟並彈一個清楚的音。'):'收音尚未開啟。按上方「麥克風收音」並允許瀏覽器使用麥克風。';$('sightMicState').closest?.('.sight-mic-card')?.classList.toggle('on',!!micStream)}if($('sightHeard'))$('sightHeard').textContent=names.length?names.join(' · '):micStream?'正在聽音，尚未辨識到音符':'等待開始收音';if($('readMicStatus'))$('readMicStatus').textContent=micStream?(names.length?'收音中・即時辨識：'+names.join(' · ')+'。彈出目前和弦後按「檢查目前和弦」。':'收音中・等待你彈出目前和弦；這裡會顯示辨識到的音。'):'收音尚未開啟；按上方麥克風按鈕即可用外接鋼琴作答。';if($('sightCheck')&&sightSequence&&sightIndex<sightSequence.chords.length)$('sightCheck').disabled=!micStream&&!sightSelected.size;refreshGlobalMicUi()}
function setGlobalMic(){if(micStream)stopChordMic();else startChordMic()}
function startChordMic(){if(micStream){syncPracticeMicState();return}if(!window.isSecureContext){const msg='麥克風需要 HTTPS 網址，請從和弦研究室網站開啟。';$('micFeedback').textContent=msg;if($('sightMicState'))$('sightMicState').textContent=msg;return}if(!navigator.mediaDevices?.getUserMedia){const msg='此瀏覽器無法使用麥克風；請在 iPad Safari 的網站設定中允許麥克風。';$('micFeedback').textContent=msg;if($('sightMicState'))$('sightMicState').textContent=msg;return}const requestEpoch=++micRequestEpoch;$('micFeedback').textContent='請在瀏覽器提示中允許麥克風…';if($('sightMicState'))$('sightMicState').textContent='正在請求麥克風權限…';let request;try{request=navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false})}catch(e){$('micFeedback').textContent='無法開啟麥克風：'+e.message;return}request.then(async stream=>{if(requestEpoch!==micRequestEpoch){stream.getTracks().forEach(t=>t.stop());return}micStream=stream;try{await baseAudio();micAnalyser=context.createAnalyser();micAnalyser.fftSize=16384;micAnalyser.smoothingTimeConstant=.08;micFrames=new Float32Array(micAnalyser.frequencyBinCount);micTimeFrames=new Float32Array(8192);micInput=context.createMediaStreamSource(stream);micInput.connect(micAnalyser);const track=stream.getAudioTracks?.()[0];track?.addEventListener?.('ended',()=>{if(micStream===stream)stopChordMic()},{once:true});stableMicFrames.clear();previousMicNotes.clear();resetPolyCalibration();$('micStart').disabled=false;$('micStop').disabled=false;$('micFeedback').textContent='收音已開啟。可在目前練習中直接彈奏外接鋼琴；上方綠色按鈕可停止。';refreshGlobalMicUi();syncPracticeMicState();micScan()}catch(e){stream.getTracks().forEach(t=>t.stop());micStream=null;$('micFeedback').textContent='麥克風已授權，但音訊無法啟動：'+e.message;refreshGlobalMicUi();syncPracticeMicState()}}).catch(e=>{const msg=e.name==='NotAllowedError'?'麥克風權限未開啟；請在 iPad Safari 的網站設定中允許麥克風。':'無法開啟麥克風：'+e.message;$('micFeedback').textContent=msg;if($('sightMicState'))$('sightMicState').textContent=msg;refreshGlobalMicUi()})}
function stopChordMic(){micRequestEpoch++;if(micRAF)cancelAnimationFrame(micRAF);micRAF=0;try{micStream?.getTracks().forEach(t=>t.stop());micInput?.disconnect();micAnalyser?.disconnect()}catch(e){}micStream=null;micInput=null;micAnalyser=null;micFrames=null;micTimeFrames=null;micInputDb=-120;micObserved.clear();micObservedNotes.clear();stableMicFrames.clear();previousMicNotes.clear();resetPolyCalibration();$('micStart').disabled=false;$('micStop').disabled=true;$('micProgress').textContent=chordFinder?'收音已停止・仍可點琴鍵作答':'收音已停止';$('micFeedback').textContent=chordFinder?'收音已停止；你仍可點練習琴鍵。':'需要收音時按頁面上方的麥克風按鈕。';renderMicNotes();syncPracticeMicState()}
function analyzeSinglePitch(){if(!micTimeFrames||!micAnalyser)return null;const stride=4,n=Math.floor(micTimeFrames.length/stride),rate=context.sampleRate/stride,minLag=Math.max(7,Math.floor(rate/1500)),maxLag=Math.min(Math.floor(rate/48),n-80),diff=new Float32Array(maxLag+1);let energy=0;for(let i=0;i<n;i++){const x=micTimeFrames[i*stride];energy+=x*x}if(energy/n<.000004)return null;for(let lag=minLag;lag<=maxLag;lag++){let sum=0,count=0;for(let i=0;i<n-lag;i++){const d=micTimeFrames[i*stride]-micTimeFrames[(i+lag)*stride];sum+=d*d;count++}diff[lag]=sum/count}let running=0,bestLag=0,best=1;for(let lag=minLag;lag<=maxLag;lag++){running+=diff[lag];const cmnd=running?diff[lag]* (lag-minLag+1)/running:1;if(cmnd<best){best=cmnd;bestLag=lag}if(lag>minLag&&cmnd<.16&&diff[lag]<=diff[lag-1]&&diff[lag]<=diff[lag+1]){bestLag=lag;best=cmnd;break}}if(!bestLag||best>.28)return null;let lag=bestLag;if(lag>minLag&&lag<maxLag){const a=diff[lag-1],b=diff[lag],c=diff[lag+1],den=a-2*b+c;if(Math.abs(den)>1e-9)lag+=Math.max(-.5,Math.min(.5,.5*(a-c)/den))}const midi=69+12*Math.log2(rate/lag/440),note=Math.round(midi);if(note<31||note>94||Math.abs(midi-note)>.48)return null;return (note%12+12)%12}
function micScan(){
 if(!micStream||!micAnalyser)return;
 const now=performance.now(),learn=document.body.dataset.workspace==='accomp'||(!$('sightWorkspace').hidden&&missionKind==='guided'),practice=!$('sightWorkspace').hidden;
 if(micTimeFrames){micAnalyser.getFloatTimeDomainData(micTimeFrames);let sum=0;for(const x of micTimeFrames)sum+=x*x;micInputDb=20*Math.log10(Math.sqrt(sum/micTimeFrames.length)+1e-8)}
 const singleMode=(learn&&((currentLevel()==='beginner'&&guideStage()>0&&guideStage()<7)||exploreChallenge?.active))||(practice&&((missionKind==='mic'&&chordFinder)||(missionKind==='build'&&buildTask&&!buildTask.done)));
 let singleOnset=null;
 if(now<micIgnoreUntil){micObserved.clear();micObservedNotes.clear();singleMicLatched=null;singleMicCandidate=null;singleMicCount=0;polyStableKey='';polyStableSince=now;syncPracticeMicState();micRAF=requestAnimationFrame(micScan);return}
 if(singleMode&&micTimeFrames&&now-lastSingleMicScan>=75){lastSingleMicScan=now;singleMicPitch=analyzeSinglePitch();if(singleMicPitch===null){singleMicSilence++;singleMicCandidate=null;singleMicCount=0;if(singleMicSilence>=2)singleMicLatched=null}else{singleMicSilence=0;if(singleMicPitch===singleMicCandidate)singleMicCount++;else{singleMicCandidate=singleMicPitch;singleMicCount=1}if(singleMicCount>=2&&singleMicPitch!==singleMicLatched){singleOnset=singleMicPitch;singleMicLatched=singleMicPitch}}}
 if(singleMode&&now<polyCalibrationUntil)analyzePitchNotes();
 if(singleMode){micObserved.clear();micObservedNotes.clear();if(singleMicPitch!==null)micObserved.set(singleMicPitch,now)}
 else if(now-lastPolyScan>=65){lastPolyScan=now;const detected=analyzePitchNotes(),stable=stablePolyNotes(detected,now);micObserved.clear();micObservedNotes.clear();for(const n of stable){micObserved.set(n%12,now);micObservedNotes.set(n,now)}if(practice&&missionKind==='read')acceptSightInput(stable,'microphone',now)}
 if(singleOnset!==null&&practice&&missionKind==='mic'&&chordFinder)chordFinderInput(singleOnset,'microphone');
 if(singleOnset!==null&&learn){if(currentLevel()==='beginner'&&guideStage()>0&&guideStage()<7&&singleOnset===guideExpected()%12){guideKeyTap(guideExpected());$('guideFeedback').textContent='收音辨識到 '+missionTextName(singleOnset)+'，找對了！'}else if(exploreChallenge?.active)challengeInput(singleOnset)}
 if(singleOnset!==null&&practice&&missionKind==='build'&&buildTask&&!buildTask.done&&now>=buildMicReadyAt&&singleOnset===buildTask.expected)answerBuild(buildTask.expected,null);
 renderMicNotes();syncPracticeMicState();micRAF=requestAnimationFrame(micScan)
}
