  $('playbackAccept').onclick=()=>finish(true);$('playbackCancel').onclick=()=>finish(false);
  dialog.oncancel=e=>{e.preventDefault();finish(false)};
  if(dialog.showModal)dialog.showModal();else finish(window.confirm('播放前關閉麥克風收音？播放後可按「恢復收音」。'));
