// Keep coherent stable notes, not an exact spectrum that must remain unchanged.
let noteStability=new Map(),accompanimentEvidence=new Map(),lastEvidenceIndex=-1,previousHarmony=null,awaitingHarmonyChange=false;
function resetAccompanimentEvidence(){accompanimentEvidence.clear();noteStability.clear();lastEvidenceIndex=sightIndex;previousHarmony=null;awaitingHarmonyChange=false;}
function stablePolyNotes(detected,now){const present=new Set(detected);for(const n of present){const old=noteStability.get(n);noteStability.set(n,{since:old&&now-old.last<160?old.since:now,last:now})}for(const [n,v]of noteStability)if(now-v.last>130)noteStability.delete(n);return [...noteStability].filter(([,v])=>now-v.since>=110).map(([n])=>n).sort((a,b)=>a-b)}
const directSightInput=acceptSightInput;
acceptSightInput=function(notes,source,now=performance.now()){
 if(source!=='microphone'||$('recognitionStyle').value==='together')return directSightInput(notes,source,now);
 if(lastEvidenceIndex!==sightIndex){accompanimentEvidence.clear();lastEvidenceIndex=sightIndex}
 if(!notes.length){directSightInput([],source,now)}
 const signature=[...new Set(notes.map(n=>n%12))].sort((a,b)=>a-b).join(',')+'|'+(notes.length?Math.min(...notes)%12:'');
 if(signature===sightLastAccepted&&!sightReleased)return false;
 if(awaitingHarmonyChange&&notes.some(n=>!previousHarmony.has(n%12))){accompanimentEvidence.clear();awaitingHarmonyChange=false}
 const windowMs=Number($('recognitionWindow').value)||3500;
 for(const [n,t]of accompanimentEvidence)if(now-t>windowMs)accompanimentEvidence.delete(n);
 for(const n of notes)accompanimentEvidence.set(n,now);
 if(!notes.length)return false;
 const heard=[...accompanimentEvidence.keys()];
 $('accompanimentHeard').textContent='這一段聽到：'+[...new Set(heard.map(n=>n%12))].map(sightName).join(' · ');
 const current=sightSequence?.chords[sightIndex];
 const ok=directSightInput(heard,source,now);
 if(ok){previousHarmony=new Set(qualities[current.q][2].map(i=>(current.root+i)%12));awaitingHarmonyChange=true;accompanimentEvidence.clear();lastEvidenceIndex=sightIndex;$('accompanimentHeard').textContent='已通過，等待下一個和弦。'}return ok;
};
$('recognitionStyle').onchange=()=>{resetAccompanimentEvidence();$('accompanimentHeard').textContent=$('recognitionStyle').value==='together'?'同時彈奏：確認一起響起的和弦音。':'分解／雙手伴奏：可先彈低音，再彈右手；同一格的音會短暫累積。'};
$('recognitionWindow').onchange=resetAccompanimentEvidence;
