function enableKeyboardSwipe102(host){for(const key of host.children){if(!key.onpointerdown||key._swipe102)continue;key._swipe102=true;const down=key.onpointerdown;let start=null;key.onpointerdown=e=>{if(keyboardView102==='scroll'&&e.pointerType!=='mouse'){start={x:e.clientX,y:e.clientY};return}down(e)};key.onpointerup=e=>{const p=start;start=null;if(p&&Math.hypot(e.clientX-p.x,e.clientY-p.y)<9)down(e)};key.onpointercancel=()=>{start=null}}}
