const teaching=document.createElement('section');teaching.id='teachWorkspace';teaching.hidden=true;
teaching.innerHTML=`<div class="lesson-header"><div><h2>一步一步，聽懂和弦</h2><p>先看示範，再動手試；老師可隨時切換課程。</p></div><select id="lessonSelect" aria-label="選擇教學課程"><option value="0">01　大三和弦</option><option value="1">02　大三與小三</option><option value="2">03　認識轉位</option><option value="3">04　和弦連接</option></select></div><div class="lesson-steps" aria-label="教學步驟"><button data-phase="0">1　看示範</button><button data-phase="1">2　跟著做</button><button data-phase="2">3　小挑戰</button></div><div class="lesson-card"><span id="lessonKicker" class="lesson-kicker"></span><h3 id="lessonPrompt"></h3><p id="lessonExplanation"></p><div id="lessonNotes" class="lesson-notes"></div><div class="lesson-actions"><button id="lessonDemo" class="mission-primary">聽示範</button><button id="lessonTransform" class="listen"></button><button id="lessonHint" class="listen">顯示提示</button><button id="lessonClear" class="listen">重新作答</button><button id="lessonStop" class="listen">停止聲音</button></div><div id="lessonFeedback" class="lesson-feedback" role="status" aria-live="polite"></div></div><div class="lesson-keyboard-wrap"><div class="lesson-keyboard-label"><span>點琴鍵試音／選音</span><span id="lessonRange"></span></div><div id="lessonKeyboard" class="lesson-keyboard"></div></div><div class="lesson-footer"><button id="lessonPrev" class="listen">上一步</button><span>也可在真實鋼琴上練習，由老師按下一步。</span><button id="lessonNext" class="mission-primary">下一步</button></div><p class="lesson-settings-note">本模式依課程循序安排內容；上方難度用於自由探索與和弦練習。</p>`;
$('learnWorkspace').before(teaching);
let lessonIndex=0,lessonPhase=0,lessonVariant=0,lessonAnswer=new Set(),lessonHint=false,lessonDemoEpoch=0;
const LESSONS=[
 {name:'大三和弦',prompts:['C 大三和弦：根音、三音、五音','依序找出 C、E、G','換你組出 F 大三和弦'],explain:['從 C 開始，加入 E 與 G。根音到三音是大三度，三音到五音是小三度。','點下方琴鍵選音，再點同一鍵可以取消。先找根音，再找三音與五音。','想想 F 的三音與五音。先試試看，需要時再顯示提示。'],sets:[[0,4,7],[0,4,7],[5,9,12]],labels:['C · E · G','C · E · G','F · A · C'],hint:'從 F 往上：大三度到 A，再小三度到 C。'},
 {name:'大三與小三',prompts:['只改一個音，聲音就不同','把 C 大三和弦變成 Cm','組出 Dm：D 小三和弦'],explain:['C–E–G 是大三和弦；把 E 降低半音成 E♭，就是 Cm。根音與五音保留。','根音 C、五音 G 不動；三音改成 E♭。選出這三個音。','從 D 出發，先找小三度，再找純五度。'],sets:[[0,4,7],[0,3,7],[2,5,9]],labels:['C · E · G','C · E♭ · G','D · F · A'],hint:'Dm 的構成音是 D、F、A。'},
 {name:'認識轉位',prompts:['同樣三個音，換一個最低音','彈出 C 和弦第一轉位','彈出 F 和弦第一轉位'],explain:['按「搬高最低音」，把最低的音提高八度。依序比較原位、第一轉位、第二轉位。','將低音 C 搬高八度：由低到高是 E、G、C。請選出這三個位置。','先想 F–A–C，再把最低的 F 搬高八度。這題要留意實際音高位置。'],sets:[[0,4,7],[4,7,12],[9,12,17]],labels:['C · E · G','E · G · C','A · C · F'],hint:'第一轉位由低到高為 A、C、F；最低音是三音 A。'},
 {name:'和弦連接',prompts:['C → F：讓手移動得更少','保留 C，讓 E→F、G→A','C → G：找出較近的配置'],explain:['先比較 C–E–G → F–A–C，再聽 C–E–G → C–F–A。後者使用 F 第二轉位，保留共同音 C。','請在同一音域選出 C–F–A。這是 F 第二轉位，最低音是五音 C。','從 C–E–G 接到 G 和弦：保留 G，C 下行半音到 B，E 下行到 D。請選出 B–D–G。'],sets:[[0,4,7],[0,5,9],[-1,2,7]],labels:['C · E · G → C · F · A','C · F · A','B · D · G'],hint:'選 C 下方的 B、同音域的 D 與 G；這是 G 第一轉位。'}
];
function lessonBase(){return Number($('octave').value)||48}
function lessonName(n){return ($('noteDisplay').value==='numeral'?['1','♯1','2','♭3','3','4','♯4','5','♭6','6','♭7','7']:FLAT_NAMES)[positiveModulo(n)]+($('noteDisplay').value==='name'?Math.floor(n/12)-1:'')}
function lessonTarget(){const l=LESSONS[lessonIndex];if(lessonPhase===0&&lessonIndex===1)return lessonVariant%2?[0,3,7]:[0,4,7];if(lessonPhase===0&&lessonIndex===2)return [[0,4,7],[4,7,12],[7,12,16]][lessonVariant%3];if(lessonPhase===0&&lessonIndex===3)return lessonVariant%2?[0,5,9]:[5,9,12];return l.sets[lessonPhase]}
function drawLessonKeyboard(){const base=lessonBase(),low=base-1,high=base+24,white=[];for(let n=low;n<=high;n++)if(natural.includes(positiveModulo(n)))white.push(n);const host=$('lessonKeyboard');host.innerHTML='';const target=new Set(lessonTarget().map(x=>base+x));for(let n=low;n<=high;n++){const b=document.createElement('button'),black=!natural.includes(positiveModulo(n));b.type='button';b.className=(black?'black ':'')+((lessonPhase===0||lessonHint)&&target.has(n)?'marked ':'')+(lessonAnswer.has(n)?'pressed':'');b.dataset.note=n;b.setAttribute('aria-label',lessonName(n));b.setAttribute('aria-pressed',String(lessonAnswer.has(n)));b.textContent=lessonName(n);if(black){b.style.width=(100/white.length*.64)+'%';b.style.left=(white.filter(x=>x<n).length/white.length*100-100/white.length*.32)+'%'}b.onclick=()=>lessonTap(n);host.append(b)}$('lessonRange').textContent=lessonName(low)+' — '+lessonName(high)}
function renderLesson(){const l=LESSONS[lessonIndex];$('lessonSelect').value=lessonIndex;$('lessonKicker').textContent='第 '+(lessonIndex+1)+' 課 · '+l.name;$('lessonPrompt').textContent=l.prompts[lessonPhase];$('lessonExplanation').textContent=l.explain[lessonPhase];$('lessonNotes').textContent=lessonPhase===0||lessonHint?lessonTarget().map(x=>lessonName(lessonBase()+x)).join(' · '):'先試試，再看提示';if(lessonIndex===2&&lessonPhase===0)$('lessonNotes').textContent=inversionName(lessonVariant%3)+'：'+$('lessonNotes').textContent;$('lessonTransform').hidden=lessonPhase!==0||lessonIndex===0;$('lessonTransform').textContent=lessonIndex===1?(lessonVariant%2?'切回 C 大三':'改成 Cm'):lessonIndex===2?'搬高最低音':(lessonVariant%2?'比較：都用原位':'比較：較近的轉位');$('lessonHint').hidden=lessonPhase===0;$('lessonClear').hidden=lessonPhase===0;$('lessonDemo').textContent=lessonPhase===2?'聽目標和弦':'聽示範';$('lessonPrev').disabled=lessonIndex===0&&lessonPhase===0;$('lessonNext').textContent=lessonPhase<2?'下一步':lessonIndex<3?'下一課':'完成・自由探索';document.querySelectorAll('[data-phase]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.phase)===lessonPhase);b.setAttribute('aria-pressed',String(Number(b.dataset.phase)===lessonPhase))});drawLessonKeyboard()}
function resetLesson(){stop();lessonDemoEpoch++;lessonAnswer.clear();lessonHint=false;lessonVariant=0;$('lessonHint').textContent='顯示提示';$('lessonFeedback').textContent='';renderLesson()}
async function lessonSound(groups){stop();const token=generation,epoch=++lessonDemoEpoch;try{await audio();if(token!==generation||epoch!==lessonDemoEpoch)return;const start=context.currentTime+.05;groups.forEach((group,i)=>{const when=start+i*1.25;group.forEach(n=>tone(n,1.05,when,.55));later(()=>{if(epoch!==lessonDemoEpoch)return;document.querySelectorAll('#lessonKeyboard button').forEach(b=>b.classList.toggle('pressed',group.includes(Number(b.dataset.note))))},Math.max(0,(when-context.currentTime)*1000))});later(()=>{if(epoch===lessonDemoEpoch)drawLessonKeyboard()},groups.length*1250+100)}catch(e){$('lessonFeedback').textContent=e.name==='PlaybackCancelled'?'已取消示範。':'聲音尚未啟動，請再按一次。'}}
function lessonTap(n){lessonSound([[n]]);if(lessonPhase===0)return;lessonAnswer.has(n)?lessonAnswer.delete(n):lessonAnswer.add(n);const target=lessonTarget().map(x=>lessonBase()+x);const exact=lessonIndex>=2;const actual=new Set([...lessonAnswer].map(x=>exact?x:positiveModulo(x))),wanted=new Set(target.map(x=>exact?x:positiveModulo(x)));const correct=actual.size===wanted.size&&[...actual].every(x=>wanted.has(x));$('lessonFeedback').textContent=correct?'答對了！可以再聽一次，或繼續下一步。':lessonAnswer.size?'已選 '+[...lessonAnswer].sort((a,b)=>a-b).map(lessonName).join(' · '):'';drawLessonKeyboard()}
$('lessonSelect').onchange=()=>{lessonIndex=Number($('lessonSelect').value);lessonPhase=0;resetLesson()};
document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{lessonPhase=Number(b.dataset.phase);resetLesson()});
$('lessonTransform').onclick=()=>{lessonVariant++;renderLesson();$('lessonDemo').click()};
$('lessonDemo').onclick=()=>{const base=lessonBase(),target=lessonTarget().map(x=>x+base);lessonSound(lessonPhase===0&&lessonIndex===3?[[base,base+4,base+7],target]:lessonPhase===0&&lessonIndex===0?[...target.map(x=>[x]),target]:[target])};
