let appRegistration=null,offlineReady=false,appReloadRequested=false;
function updateOfflineLabel(){const label=offlineReady?(navigator.onLine?'可離線使用':'離線使用中'):(navigator.onLine?'準備離線資料':'尚未備妥離線資料');$('appStatus').textContent=label;$('appStatus').classList.toggle('ready',offlineReady);$('appOfflineDetail').textContent=offlineReady?'教學、琴鍵、鋼琴音色與和弦譜已下載。可先開飛航模式測試；系統清理網站資料後需重新連網下載。':'首次使用請保持連網，等待離線資料下載完成。'}
function requestOfflineStatus(){(navigator.serviceWorker?.controller||appRegistration?.active)?.postMessage({type:'OFFLINE_STATUS'})}
window.addEventListener('online',()=>{updateOfflineLabel();appRegistration?.update().catch(()=>{});requestOfflineStatus()});window.addEventListener('offline',updateOfflineLabel);
$('appCheckUpdate').onclick=async()=>{if(!navigator.onLine){$('appOfflineDetail').textContent='目前離線；連網後才能檢查更新。';return}if(!appRegistration){$('appOfflineDetail').textContent='離線功能尚未註冊成功，請重新整理後再試。';return}try{$('appOfflineDetail').textContent='正在檢查更新…';await appRegistration.update();if(appRegistration.waiting){updateBar.hidden=false;$('appOfflineDetail').textContent='新版已備妥，可按「儲存並更新」。'}else if(appRegistration.installing){$('appOfflineDetail').textContent='新版下載中，完成後會顯示更新按鈕。'}else{$('appOfflineDetail').textContent='目前沒有待更新版本。';requestOfflineStatus()}}catch(e){$('appOfflineDetail').textContent='目前無法檢查更新，稍後再試；已下載的版本可繼續使用。'}};
$('appApplyUpdate').onclick=()=>{if(!appRegistration?.waiting)return;saveSong();saveLyrics();stop();if(micStream)stopChordMic();appReloadRequested=true;appRegistration.waiting.postMessage({type:'ACTIVATE_UPDATE'})};
if('serviceWorker' in navigator&&location.protocol==='https:'){
 navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_STATUS'){offlineReady=!!e.data.ready;updateOfflineLabel()}});
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(appReloadRequested){location.reload();return}requestOfflineStatus()});
 navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(reg=>{
  appRegistration=reg;if(reg.waiting)updateBar.hidden=false;requestOfflineStatus();
  function watchInstalling(){const worker=reg.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateBar.hidden=false}else if(worker.state==='redundant'&&!offlineReady){$('appOfflineDetail').textContent='離線下載未完成，請保持連網後重新整理。'}})}reg.addEventListener('updatefound',watchInstalling);watchInstalling();
  navigator.serviceWorker.ready.then(()=>{requestOfflineStatus();navigator.storage?.persist?.().catch(()=>{})});
 }).catch(()=>{$('appStatus').textContent='線上模式';$('appOfflineDetail').textContent='此瀏覽器未能啟用離線功能；請用 Safari 或 Chrome 重新開啟。'});
}else{$('appStatus').textContent='線上模式';$('appOfflineDetail').textContent='離線與安裝功能需要 HTTPS 網址及支援的瀏覽器。'}


